esp_err_t screen_store_reset_to_defaults(void)
{
    if (!s_is_mounted) return ESP_ERR_INVALID_STATE;

    ESP_LOGW(TAG, "Resetting all screens and images to factory defaults!");

    // Delete existing screens
    DIR *dir = opendir(SCREENS_DIR);
    if (dir) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG || entry->d_type == DT_UNKNOWN) {
                char path[512];
                snprintf(path, sizeof(path), "%s/%s", SCREENS_DIR, entry->d_name);
                remove(path);
            }
        }
        closedir(dir);
    }

    // Delete existing images
    dir = opendir(IMAGES_DIR);
    if (dir) {
        struct dirent *entry;
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG || entry->d_type == DT_UNKNOWN) {
                char path[512];
                snprintf(path, sizeof(path), "%s/%s", IMAGES_DIR, entry->d_name);
                remove(path);
            }
        }
        closedir(dir);
    }

    // Re-seed defaults
    for (size_t i = 0; i < DEFAULT_SCREENS_COUNT; i++) {
        char path[128];
        snprintf(path, sizeof(path), "%s/%s.json", SCREENS_DIR, DEFAULT_SCREENS[i].name);
        FILE *f = fopen(path, "wb");
        if (f) {
            size_t len = DEFAULT_SCREENS[i].end - DEFAULT_SCREENS[i].start;
            fwrite(DEFAULT_SCREENS[i].start, 1, len, f);
            fclose(f);
        }
    }

    for (size_t i = 0; i < DEFAULT_IMAGES_COUNT; i++) {
        char path[128];
        snprintf(path, sizeof(path), "%s/%s.json", IMAGES_DIR, DEFAULT_IMAGES[i].name);
        FILE *f = fopen(path, "wb");
        if (f) {
            size_t len = DEFAULT_IMAGES[i].end - DEFAULT_IMAGES[i].start;
            fwrite(DEFAULT_IMAGES[i].start, 1, len, f);
            fclose(f);
        }
    }

    ESP_LOGI(TAG, "Successfully restored %u default screens and %u default images",
             (unsigned)DEFAULT_SCREENS_COUNT, (unsigned)DEFAULT_IMAGES_COUNT);
    return ESP_OK;
}
